function heroArt(){const blocks=Object.entries(BEST).map(([id,r])=>`<rect x="${95+r.x*45}" y="${290-(r.y+r.h)*45}" width="${r.w*45-3}" height="${r.h*45-3}" rx="2" fill="${COLORS[id]}"/><text x="${95+(r.x+r.w/2)*45}" y="${290-(r.y+r.h/2)*45+6}" text-anchor="middle" fill="#fffdf4" font-family="Georgia,serif" font-size="20">${id}</text>`).join('');return `<div class="hero-art"><svg viewBox="0 0 500 350" role="img" aria-label="${T('五块模块的紧凑布局，包围盒 6×4','A compact five-block layout in a 6×4 bounding box')}"><defs><pattern id="heroGrid" width="45" height="45" patternUnits="userSpaceOnUse" x="95" y="20"><path d="M45 0H0V45" fill="none" stroke="#dedfce" stroke-width=".8"/></pattern></defs><rect x="51" y="20" width="405" height="270" fill="url(#heroGrid)"/><rect x="95" y="110" width="270" height="180" fill="none" stroke="#789580" stroke-width="1" stroke-dasharray="4 5"/>${blocks}<path d="M95 315H365M95 309V321M365 309V321" stroke="#8d9a86"/><text x="230" y="338" text-anchor="middle" font-size="13" fill="#607369" font-family="Consolas,monospace">6 × 4 = 24</text><text x="374" y="130" font-size="10" fill="#657a6d" font-family="Consolas,monospace">Σ area = 23</text><text x="374" y="151" font-size="10" fill="#657a6d" font-family="Consolas,monospace">1 ${T('格空余','empty unit')}</text><path d="M365 172H406V240H365" stroke="#a7b29f" fill="none"/><text x="20" y="91" font-family="Consolas,monospace" font-size="11" fill="#778878" transform="rotate(-90 20 91)">FIVE BLOCKS / ONE PROBLEM</text></svg><div class="art-label"><span>CONSTRAINT → REPRESENTATION → SEARCH</span><span>10 × 8 OUTLINE</span></div></div>`;}
