function initInteractivePage(){
 const controller=new AbortController(),signal=controller.signal,frame=$('#interactive-teaching-frame');if(!frame)return;
 const teachingURL=new URL(frame.getAttribute('src'),location.href);teachingURL.searchParams.set('lang',lang);if(teachingRestore){teachingURL.searchParams.set('scene',teachingRestore.scene);teachingURL.searchParams.set('fraction',teachingRestore.fraction);teachingRestore=null;}frame.src=teachingURL.href;
 const pauseChild=()=>frame.contentWindow?.postMessage({type:'interactive-pause'},location.origin);
 window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow)return;const d=e.data;
  if(d?.type==='interactive-height'&&Number.isFinite(d.height)&&d.height>=300&&d.height<=6000)frame.style.height=d.height+'px';
  if(d?.type==='interactive-play'){$('#sample-video')?.pause();film?.audio.pause();}
  if(d?.type==='interactive-go-lab'){$('#lab')?.scrollIntoView({behavior:'smooth',block:'start'});pauseChild();}
 },{signal});
 $('#sample-video')?.addEventListener('play',pauseChild,{signal});
 const reveal=()=>{const target=document.getElementById(location.hash.slice(1));if(!target)return;for(let e=target.parentElement;e;e=e.parentElement)if(e.tagName==='DETAILS')e.open=true;};
 window.addEventListener('hashchange',reveal,{signal});reveal();onePageCleanup=()=>{pauseChild();controller.abort();};
}
